import React, { createContext, useContext, useState, useEffect } from 'react';

const CurrencyContext = createContext();

// Static Dictionary for conversion (Base: INR)
const STATIC_RATES = {
    INR: 1,
    USD: 0.012,
    EUR: 0.011,
    GBP: 0.0094,
    CAD: 0.016,
    AUD: 0.018,
    AED: 0.044,
    JPY: 1.83,
    CNY: 0.086,
    SGD: 0.016,
    HKD: 0.094,
    NZD: 0.020
};

// Map timezones to currency codes
const getCurrencyFromTimezone = (tz) => {
    if (!tz) return 'INR';

    if (tz.startsWith('America/')) {
        if (tz.includes('Toronto') || tz.includes('Vancouver')) return 'CAD';
        return 'USD';
    }
    if (tz.startsWith('Europe/')) {
        if (tz.includes('London')) return 'GBP';
        return 'EUR';
    }
    if (tz.startsWith('Australia/')) return 'AUD';
    if (tz.includes('Auckland')) return 'NZD';
    if (tz.includes('Asia/Dubai')) return 'AED';
    if (tz.includes('Asia/Tokyo')) return 'JPY';
    if (tz.includes('Asia/Shanghai')) return 'CNY';
    if (tz.includes('Asia/Singapore')) return 'SGD';
    if (tz.includes('Asia/Hong_Kong')) return 'HKD';
    if (tz.includes('Asia/Kolkata') || tz.includes('Asia/Calcutta')) return 'INR';

    // Default for unrecognized global regions
    return 'USD'; 
};

export const CurrencyProvider = ({ children }) => {
    const [currencyCode, setCurrencyCode] = useState('INR');
    const [exchangeRate, setExchangeRate] = useState(1);

    useEffect(() => {
        try {
            // Native, offline geo-location via clock
            const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
            const detectedCurrency = getCurrencyFromTimezone(tz);

            // Get rate, default to 1 if missing for some reason
            const rate = STATIC_RATES[detectedCurrency] || 1;

            setCurrencyCode(detectedCurrency);
            setExchangeRate(rate);
        } catch (error) {
            console.error("Currency detection failed:", error);
            setCurrencyCode('INR');
            setExchangeRate(1);
        }
    }, []);

    // Core Formatting Hook
    const formatPrice = (priceInINR) => {
        if (!priceInINR) return '';

        // Convert the price mathematically
        const converted = priceInINR * exchangeRate;

        // Format with native browser tools to get correct commas and symbols
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: currencyCode,
            minimumFractionDigits: 0,
            maximumFractionDigits: 2
        }).format(converted);
    };

    // Return mathematical amount for checkout payloads WITHOUT the symbol
    const getConvertedAmount = (priceInINR) => {
        if (!priceInINR) return 0;
        return Number((priceInINR * exchangeRate).toFixed(2));
    };

    return (
        <CurrencyContext.Provider value={{
            currencyCode,
            exchangeRate,
            formatPrice,
            getConvertedAmount
        }}>
            {children}
        </CurrencyContext.Provider>
    );
};

export const useCurrency = () => useContext(CurrencyContext);
